import React from 'react';
import { VerticalForm } from '../form';
import { Card, Button } from 'react-bootstrap';

function CardViewBox(props) {
    const { card, setCard, children, cardHeader, cancelBtn = true, cardSize, saveBtn = true, handleSubmit, btnName = false, isEdit, cardHead = false, backgroundColor = "", headerBg = "", variant = "primary", betweenContent = <></> } = props;
    const handleClose = () => {
        setCard(false);
    };

    return (
        <React.Fragment>
            <Card show={card ? "true" : "false"} centered={"true"} size={cardSize}>
                {
                    cardHeader &&
                    <Card.Header style={{ backgroundColor: headerBg }}>
                        <Card.Title as="h4">{`${isEdit ? 'Edit ' : cardHead ? '' : ''} ${cardHeader}`}</Card.Title>
                    </Card.Header>
                }
                <Card.Body style={{ backgroundColor: backgroundColor }}>
                    <VerticalForm onSubmit={() => { }} defaultValues={{}}>
                        {children}

                        <div className='d-flex justify-content-end'>
                            {saveBtn && <Button
                                variant={variant}
                                className="waves-effect waves-light me-1"
                                type="button"
                                onClick={handleSubmit}>
                                {`${isEdit ? 'Update' : btnName ? btnName : 'Save'}`}
                            </Button>}
                            {cancelBtn && <Button variant="danger" className="waves-effect waves-light" onClick={handleClose}>
                                Cancel
                            </Button>}
                        </div>

                        {betweenContent && betweenContent}
                    </VerticalForm>
                </Card.Body>
            </Card>
        </React.Fragment>
    );
}

export default CardViewBox;
