import React, { useEffect, useRef, useState, } from 'react';
import { useNavigate } from 'react-router-dom';
import { Badge, Col, Row, Spinner, Button } from 'react-bootstrap';
import ModelViewBox from '../../components/Atom/ModelViewBox';
import FormLayout from '../../utils/formLayout';
import { paymentContainer, staffContainer } from './formFieldData';
import Table from '../../components/Table';
import { dateConversion, findArrObj, numberWithCommas, showConfirmationDialog, showMessage } from '../../utils/AllFunction';
import { createHolidayRequest, createLoanPaymentRequest, deletePaymentHistoryRequest, getAddLoanRequest, getHolidayRequest, getLoanListDetailsRequest, getLoanListRequest, getStaffRequest, resetCreateHoliday, resetCreateLoanPayment, resetDeletePaymentHistory, resetGetAddLoan, resetGetHoliday, resetGetLoanList, resetGetLoanListDetails, resetGetStaff, resetUpdateHoliday, updateHolidayRequest } from '../../redux/actions';
import { usePageTitle, useRedux } from '../../hooks'
import { NotificationContainer } from 'react-notifications';
import _ from 'lodash';
import CardViewBox from '../../components/Atom/CardViewBox';
import moment from 'moment';
import noProfile from '../../assets/images/noprofile_images.jpg';
import { baseURL } from '../../api/ApiConfig';

function Index() {

    usePageTitle({
        title: 'Loan',
        breadCrumbItems: [
            {
                path: '/loan/payment',
                label: 'Loan',
            },
            {
                path: '/loan/addloan',
                label: 'Loan Payment',
                active: true,
            },
        ]
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'url', '/loan/payment');
    const accessIds = (pageAccessData?.[0]?.access || '').split(',').map(id => id.trim());
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)

    const navigate = useNavigate()

    const {
        // loan data
        getAddLoanSuccess,
        getAddLoanList,
        getAddLoanFailure,

        getStaffSuccess,
        getStaffList,
        getStaffFailure,

        getLoanListSuccess,
        getLoanList,
        getLoanListFailure,

        getLoanListDetailsSuccess,
        getLoanListDetails,
        getLoanListDetailsFailure,

        createLoanPaymentSuccess,
        createLoanPaymentData,
        createLoanPaymentFailure,

        deletePaymentHistorySuccess,
        deletePaymentHistoryFailure,

        errorMessage
    } = appSelector((state) => ({
        //loan data
        getAddLoanSuccess: state.addLoanReducer.getAddLoanSuccess,
        getAddLoanList: state.addLoanReducer.getAddLoanList,
        getAddLoanFailure: state.addLoanReducer.getAddLoanFailure,

        getStaffSuccess: state.staffReducer.getStaffSuccess,
        getStaffList: state.staffReducer.getStaffList,
        getStaffFailure: state.staffReducer.getStaffFailure,

        getLoanListSuccess: state.addLoanReducer.getLoanListSuccess,
        getLoanList: state.addLoanReducer.getLoanList,
        getLoanListFailure: state.addLoanReducer.getLoanListFailure,

        getLoanListDetailsSuccess: state.addLoanReducer.getLoanListDetailsSuccess,
        getLoanListDetails: state.addLoanReducer.getLoanListDetails,
        getLoanListDetailsFailure: state.addLoanReducer.getLoanListDetailsFailure,

        deletePaymentHistorySuccess: state.addLoanReducer.deletePaymentHistorySuccess,
        deletePaymentHistoryFailure: state.addLoanReducer.deletePaymentHistoryFailure,

        createLoanPaymentSuccess: state.addLoanReducer.createLoanPaymentSuccess,
        createLoanPaymentData: state.addLoanReducer.createLoanPaymentData,
        createLoanPaymentFailure: state.addLoanReducer.createLoanPaymentFailure,

        errorMessage: state.holidayReducer.errorMessage,
    }));

    const columns = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,
        },
        {
            Header: 'Loan No',
            accessor: 'loanNo',
            sort: true,
        },
        {
            Header: 'Loan',
            accessor: 'loanAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value || 0)}
                    </div>
                )
            },
        },
        {
            Header: 'Paid',
            accessor: 'totalPaidAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value || 0)}
                    </div>
                )
            },
        },
        {
            Header: 'Interest',
            accessor: 'totalInterestAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value || 0)}
                    </div>
                )
            },
        },
        {
            Header: 'Balance',
            accessor: 'balancePrincipalAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value || 0)}
                    </div>
                )
            },
        },
        // {
        //     Header: 'Loan Date',
        //     accessor: 'loanDate',
        //     Cell: ({ row }) => {
        //         return (
        //             <div>
        //                 {moment(row.original.loanDate).format("DD-MM-YYYY")}
        //             </div>
        //         )
        //     },
        // },
    ];

    const columnsPaymentHistory = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,

        },
        {
            Header: 'Payment Date',
            accessor: 'paymentDate',
            Cell: ({ row }) => {
                return (
                    <div>
                        {moment(row.original.paymentDate).format("DD-MM-YYYY")}
                    </div>
                )
            },
        },
        {
            Header: 'Remark',
            accessor: 'remark',
            Footer: () => {
                return <strong style={{ color: "green" }}>{"Total Amount : "}</strong>;
            }
        },
        {
            Header: 'Pa.',
            accessor: 'paymentAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value)}
                    </div>
                )
            },
            Footer: (info) => {
                const total = info.rows.reduce((sum, row) => {
                    const val = parseFloat(row.values.paymentAmount);
                    return sum + (isNaN(val) ? 0 : val);
                }, 0);
                return <strong style={{ color: "green" }}>{numberWithCommas(total)}</strong>;
            }
        },
        {
            Header: 'Int.',
            accessor: 'interestAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value)}
                    </div>
                )
            },
            Footer: (info) => {
                const total = info.rows.reduce((sum, row) => {
                    const val = parseFloat(row.values.interestAmount);
                    return sum + (isNaN(val) ? 0 : val);
                }, 0);
                return <strong style={{ color: "green" }}>{numberWithCommas(total)}</strong>;
            }
        },
        {
            Header: 'Pri.',
            accessor: 'principalAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value)}
                    </div>
                )
            },
            Footer: (info) => {
                const total = info.rows.reduce((sum, row) => {
                    const val = parseFloat(row.values.principalAmount);
                    return sum + (isNaN(val) ? 0 : val);
                }, 0);
                return <strong style={{ color: "green" }}>{numberWithCommas(total)}</strong>;
            }
        },
        {
            Header: 'Bal.',
            accessor: 'balanceLoanAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value)}
                    </div>
                )
            },
        },
        {
            Header: 'At.',
            accessor: 'actions',
            Cell: ({ row }) => {
                const activeChecker = row.original.isActive
                return (
                    <div>
                        {
                            (roleIdforRole == 1 || _.includes(accessIds, '3')) &&
                            <span
                                className={`text-danger cursor-pointer`}
                                onClick={() =>
                                    showConfirmationDialog(
                                        "You want to Delete?",
                                        () => onDeleteForm(row.original, row.index, activeChecker),
                                        'Yes'
                                    )
                                }>
                                {
                                    <i className={'fe-trash-2'}></i>
                                }
                            </span>
                        }
                    </div>
                )
            }
        }
    ];

    const [state, setState] = useState({});
    const [parentList, setParentList] = useState([]);
    const [parentPaymentList, setParentPaymentList] = useState([]);
    const [optionListState, setOptionListState] = useState({
        staffList: [],
    });
    const [isLoading, setIsLoading] = useState(false);
    const [errors, setErrors] = useState([]);

    const errorHandle = useRef();

    useEffect(() => {
        setIsLoading(true)
        dispatch(getHolidayRequest());
        const branchReq = {
            branchId: branchIdforRole,
        }
        dispatch(getStaffRequest(roleIdforRole != 1 && branchReq));
    }, []);

    useEffect(() => {
        if (getLoanListSuccess) {
            setIsLoading(false)
            setParentList(getLoanList);
            dispatch(resetGetLoanList())
        } else if (getLoanListFailure) {
            setIsLoading(false)
            setParentList([])
            dispatch(resetGetLoanList())
        }
    }, [getLoanListSuccess, getLoanListFailure]);

    useEffect(() => {
        if (getAddLoanSuccess) {
            setIsLoading(false);
            const obj = {
                "Staff Name": getAddLoanList[0]?.staffName,
                "Staff Code": getAddLoanList[0]?.staffCode,
                "Contact No": getAddLoanList[0]?.contactNo,
                "Address": getAddLoanList[0]?.address,
                "Designation": getAddLoanList[0]?.designationName,
                "Loan No": getAddLoanList[0]?.loanNo,
                "Loan Date": moment(getAddLoanList[0]?.loanDate).format("DD-MM-YYYY"),
                "Interest Rate": `${getAddLoanList[0]?.interestRate}%`,
                "Loan Amount": `Rs. ${numberWithCommas(getAddLoanList[0]?.loanAmount)}`,
                "Process Fees": `Rs. ${numberWithCommas(getAddLoanList[0]?.processFees)}`,
                "Tenure Period": `${getAddLoanList[0]?.tenurePeriod} Months`,
                "Disbursed Type": getAddLoanList[0]?.disbursedTypeName,
            }
            setState({
                ...state,
                loanDetails: obj,
                staffProfile: getAddLoanList[0]?.staffProfile,
                staffDetails: getAddLoanList[0]
            })
            // setParentList(getAddLoanList);
            dispatch(resetGetAddLoan());
        } else if (getAddLoanFailure) {
            setIsLoading(false);
            setParentList({});
            dispatch(resetGetAddLoan());
        }
    }, [getAddLoanSuccess, getAddLoanFailure]);

    useEffect(() => {
        if (getLoanListDetailsSuccess) {
            setIsLoading(false)
            setParentPaymentList(getLoanListDetails)
            setState({
                ...state,
                loanDetailsArray: getLoanListDetails
            })
            dispatch(resetGetLoanListDetails())
        } else if (getLoanListDetailsFailure) {
            setIsLoading(false)
            setParentList([])
            dispatch(resetGetLoanListDetails())
        }
    }, [getLoanListDetailsSuccess, getLoanListDetailsFailure]);

    useEffect(() => {
        if (getStaffSuccess) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                staffList: getStaffList,
            });
            dispatch(resetGetStaff());
        } else if (getStaffFailure) {
            setIsLoading(false);
            setParentList([]);
            dispatch(resetGetStaff());
        }
    }, [getStaffSuccess, getStaffFailure]);

    useEffect(() => {
        if (createLoanPaymentSuccess) {
            const reqList = {
                staffId: state?.staffId,
            }
            dispatch(getLoanListRequest(reqList));
            setParentPaymentList(createLoanPaymentData)
            onFormClear();
            showMessage('success', 'Created Successfully');
            dispatch(resetCreateLoanPayment())
            dispatch(getLoanListDetailsRequest());
        } else if (createLoanPaymentFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetCreateLoanPayment())
        }
    }, [createLoanPaymentSuccess, createLoanPaymentFailure]);

    useEffect(() => {
        if (deletePaymentHistorySuccess) {
            const req = {
                staffLoanId: state?.staffLoanId
            }
            dispatch(getLoanListDetailsRequest(req));
            const reqList = {
                staffId: state?.staffId,
            }
            dispatch(getLoanListRequest(reqList));
            showMessage('success', 'Deleted Successfully');
            dispatch(resetDeletePaymentHistory())
        } else if (deletePaymentHistoryFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetDeletePaymentHistory())
        }
    }, [deletePaymentHistorySuccess, deletePaymentHistoryFailure]);

    const onFormClear = () => {
        setState({
            ...state,
            paymentAmount: '',
            remark: '',
        });
    };

    const handleValidation = () => {
        errorHandle.current.validateFormFields();
    }

    const onFormSubmit = async () => {
        const submitRequest = {
            paymentDate: moment().format('YYYY-MM-DD'),
            paymentAmount: state?.paymentAmount,
            remark: state?.remark,
            staffLoanId: state?.staffLoanId,
        }
        dispatch(createLoanPaymentRequest(submitRequest))
    };

    const onDeleteForm = (data) => {
        const submitRequest = {
            isActive: 0
        }
        dispatch(deletePaymentHistoryRequest(submitRequest, data?.loanPaymentId))
    };

    const onChangeStaff = (option, formName) => {
        setState({
            ...state,
            [formName]: option[formName],
            loanDetails: {},
            staffLoanId: false,
        })
        const req = {
            staffId: option?.staffId,
        }
        dispatch(getLoanListRequest(req));
    }


    const onClickRow = (row) => {
        setState({
            ...state,
            paymentAmount: '',
            remark: '',
            staffLoanId: row?.original?.staffLoanId,
            activeRow: 'bg-success text-light',
            activeRowId: row?.index,
        })
        const req = {
            staffLoanId: row?.original?.staffLoanId
        }
        dispatch(getAddLoanRequest(req));
        dispatch(getLoanListDetailsRequest(req));
    }

    console.log("state")
    console.log(state)
    console.log("parentPaymentList")
    console.log(parentPaymentList)

    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? <div className='bg-light opacity-0.25'>
                <div className="d-flex justify-content-center m-5">
                    <Spinner className='mt-5 mb-5' animation="border" />
                </div>
            </div> :
                <>
                    <Row>
                        <Col xs={6}>
                            <CardViewBox
                                cardHeader={'Loan Details'}
                                saveBtn={false}
                                cancelBtn={false}
                                classStyle={'mb-3'}
                            >
                                <FormLayout
                                    dynamicForm={staffContainer}
                                    handleSubmit={onFormSubmit}
                                    optionListState={optionListState}
                                    setState={setState}
                                    state={state}
                                    ref={errorHandle}
                                    noOfColumns={1}
                                    onChangeCallBack={{ "onChangeStaff": onChangeStaff }}
                                    errors={errors}
                                    setErrors={setErrors}
                                />
                                {
                                    state?.staffId &&
                                    <Table
                                        columns={columns}
                                        Title={false}
                                        data={parentList || []}
                                        activeRow={state?.activeRow}
                                        activeRowId={state?.activeRowId}
                                        isSearchable={false}
                                        pagination={false}
                                        onClickRow={onClickRow}
                                        footerTbl={false}
                                        toggle={false}
                                    />
                                }
                                {
                                    state?.staffId && state?.staffLoanId && state?.loanDetails &&
                                    <div>
                                        <div className="d-flex align-items-start" style={{ gap: '20px' }}>
                                            {/* Left: Staff Image */}
                                            <div>
                                                <img
                                                    src={state?.staffProfile ? `${baseURL}${state?.staffProfile}` : noProfile}
                                                    alt="staffProfile"
                                                    crossOrigin="anonymous"
                                                    onError={(e) => {
                                                        e.target.onerror = null;
                                                        e.target.src = noProfile;
                                                    }}
                                                    style={{ width: "100px", height: "100px", objectFit: "cover", borderRadius: '8px' }}
                                                />
                                            </div>

                                            {/* Right: Staff Loan Details without borders */}
                                            <div style={{ flex: 1 }}>
                                                <table style={{ width: '100%', borderCollapse: 'collapse', border: 'none' }}>
                                                    <tbody>
                                                        {Object.entries(state?.loanDetails || {}).map(([key, value], index) => (
                                                            <tr key={index}>
                                                                <td style={{ fontWeight: 'bold', padding: '6px', width: '40%' }}>
                                                                    {key}
                                                                </td>
                                                                <td style={{ padding: '6px' }}>:</td>
                                                                <td style={{ padding: '6px' }}>
                                                                    {value}
                                                                </td>
                                                            </tr>
                                                        ))}
                                                    </tbody>
                                                </table>
                                            </div>
                                        </div>
                                    </div>
                                }

                            </CardViewBox>
                        </Col>

                        <Col xs={6}>
                            {state?.staffId && state?.staffLoanId && state?.loanDetails &&
                                <>
                                    <CardViewBox
                                        cardHeader={'Loan Payment Entry'}
                                        handleSubmit={handleValidation}
                                        btnName={"Pay"}
                                        variant={"success"}
                                        cancelBtn={false}
                                        betweenContent={
                                            <>
                                                <h4>Loan Payment History</h4>
                                                <Button
                                                    className='btn-secondary'
                                                    onClick={() => {
                                                        const reportState = {
                                                            ...state,
                                                            loanDetails: state.loanDetails,
                                                            staffDetails: state.staffDetails,
                                                            loanDetailsArray: parentPaymentList
                                                        };
                                                        navigate('/loan-slip-report', { state: reportState });
                                                    }}
                                                    style={{
                                                        position: 'absolute',
                                                        right: 20,
                                                        top: 15,
                                                        zIndex: 1
                                                    }}>
                                                    <span className="cursor-pointer" style={{ fontSize: "15px" }}>
                                                        <i className={'fe-printer'}></i>
                                                    </span>
                                                </Button>

                                                <Table
                                                    columns={columnsPaymentHistory}
                                                    Title={false}
                                                    data={parentPaymentList || []}
                                                    isSearchable={false}
                                                    pagination={false}
                                                    footerTbl={true}
                                                    toggle={false}
                                                />
                                            </>
                                        }
                                    >
                                        <FormLayout
                                            dynamicForm={paymentContainer}
                                            handleSubmit={onFormSubmit}
                                            optionListState={optionListState}
                                            setState={setState}
                                            state={state}
                                            ref={errorHandle}
                                            noOfColumns={1}
                                            onChangeCallBack={{ "onChangeStaff": onChangeStaff }}
                                            errors={errors}
                                            setErrors={setErrors}
                                        />
                                    </CardViewBox>
                                </>}
                        </Col>
                    </Row>

                </>
            }
        </React.Fragment >
    );
}

export default Index;
